from pathlib import Path
import xml.etree.ElementTree as ET,json,re
translations={
'Prayer':'الصلاة','Calendar':'التقويم','Qibla':'القبلة','Settings':'الإعدادات','Salati':'صلاتي','Next prayer':'الصلاة القادمة','Time until next prayer':'الوقت المتبقي للصلاة القادمة','Current prayer':'الصلاة الحالية','Prayer time ended':'انتهى وقت الصلاة','The night':'الليل','Islamic midnight':'منتصف الليل الشرعي','Last third':'الثلث الأخير','Show countdown on Lock Screen':'إظهار العد التنازلي على شاشة القفل','Schedule next prayer countdown':'جدولة العد التنازلي للصلاة القادمة','Location':'الموقع','Choose your location':'اختر موقعك','Prayer times are calculated entirely on your device.':'تُحسب مواقيت الصلاة بالكامل على جهازك.','City name':'اسم المدينة','Use current location':'استخدام الموقع الحالي','Enter coordinates':'إدخال الإحداثيات','Find your city':'ابحث عن مدينتك','Search in Arabic or English. No internet needed.':'ابحث بالعربية أو الإنجليزية دون اتصال بالإنترنت.','Done':'تم','Coordinates':'الإحداثيات','Location name':'اسم الموقع','Latitude':'خط العرض','Longitude':'خط الطول','Time zone':'المنطقة الزمنية','Save':'حفظ','Choose the IANA time zone for these coordinates. The device time zone may differ.':'اختر المنطقة الزمنية لهذه الإحداثيات؛ فقد تختلف عن منطقة الجهاز.','GPS coordinates stay exact. City names and time zones come from the nearest offline place; check the zone near borders.':'تُستخدم إحداثيات GPS الدقيقة. يُؤخذ اسم المدينة والمنطقة الزمنية من أقرب مكان في قاعدة البيانات؛ تحقق من المنطقة قرب الحدود.','A moment for prayer':'لحظة للصلاة','Precise times. A quiet space. Always offline.':'مواقيت دقيقة ومساحة هادئة، دون اتصال دائمًا.','Calculated on your device':'تُحسب على جهازك','Arabic and English':'العربية والإنجليزية','No account or subscription':'دون حساب أو اشتراك','Language':'اللغة','Choose location':'اختيار الموقع','Continue':'متابعة','Choose a city without granting location access, or use GPS when you need it. Notifications and alarms are optional and requested from Settings.':'اختر مدينة دون منح إذن الموقع، أو استخدم GPS عند الحاجة. الإشعارات والمنبهات اختيارية ويمكن تفعيلها من الإعدادات.','City':'المدينة','Calculation':'الحساب','Method':'طريقة الحساب','Hanafi Asr':'العصر وفق المذهب الحنفي','High latitudes':'خطوط العرض العالية','Manual adjustments':'التعديلات اليدوية','Hijri adjustment':'تعديل التاريخ الهجري','Display':'العرض','Appearance':'المظهر','System':'النظام','Light':'فاتح','Dark':'داكن','24-hour time':'تنسيق 24 ساعة','Western digits (0123456789) are used in both languages.':'تُستخدم الأرقام 0123456789 في اللغتين.','Prayer alerts':'تنبيهات الصلاة','Notifications and adhan':'الإشعارات والأذان','About':'حول التطبيق','Allow notifications':'السماح بالإشعارات','Allow system alarms':'السماح بمنبهات النظام','Delivery':'نوع التنبيه','Off':'إيقاف','Notification':'إشعار','System alarm':'منبه النظام','Sound':'الصوت','System sound':'صوت النظام','Silent':'صامت','Reminder before prayer':'تذكير قبل الصلاة','Play full adhan now':'تشغيل الأذان كاملًا الآن','Stop playback':'إيقاف التشغيل','Notifications follow your system settings. System alarms require separate permission. No alerts are enabled by granting permission alone.':'تتبع الإشعارات إعدادات النظام. تتطلب المنبهات إذنًا مستقلًا. منح الإذن وحده لا يفعّل التنبيهات.','Local notifications use a short excerpt under 30 seconds. Full recordings can be played here while the app is open. Full-length automatic AlarmKit playback requires physical-device validation and is not guaranteed.':'تستخدم الإشعارات مقطعًا أقصر من 30 ثانية. يمكن تشغيل التسجيل كاملًا هنا أثناء فتح التطبيق. تشغيل الأذان كاملًا تلقائيًا عبر AlarmKit غير مضمون ويحتاج إلى اختبار على جهاز فعلي.','Up to six days are prepared. Open Salati regularly to replenish the schedule; background refresh is best effort.':'تُجهز مواقيت ستة أيام. افتح صلاتي بانتظام لتجديد الجدول؛ التحديث في الخلفية غير مضمون.','Previous month':'الشهر السابق','Next month':'الشهر التالي','Today':'اليوم','Hijri calendar':'التقويم الهجري','No special observance':'لا توجد مناسبة خاصة','Umm al-Qura calendar':'تقويم أم القرى','Local moon sighting may differ. Hijri adjustments apply only to the selected current month.':'قد تختلف الرؤية المحلية للهلال. يسري تعديل التاريخ الهجري على الشهر الحالي المحدد فقط.','Calendar unavailable':'التقويم غير متاح','Qibla from true north':'اتجاه القبلة من الشمال الحقيقي','Compass unavailable. Use the true-north bearing above.':'البوصلة غير متاحة. استخدم زاوية الشمال الحقيقي أعلاه.','Compass accuracy is low. Move away from metal and calibrate your device.':'دقة البوصلة منخفضة. ابتعد عن المعادن وعاير جهازك.','Keep your phone flat and away from magnets. Confirm direction with a reliable local reference.':'ضع الهاتف أفقيًا وبعيدًا عن المغناطيس. تحقق من الاتجاه بمرجع محلي موثوق.','Unable to update':'تعذر التحديث','OK':'حسنًا','Open Salati to refresh':'افتح صلاتي لتحديث المواقيت','Next prayer':'الصلاة القادمة','Your next prayer, calculated offline.':'صلاتك القادمة، محسوبة دون اتصال.','The countdown uses system rendering. Open Salati regularly to refresh changing prayer schedules.':'يعرض النظام العد التنازلي. افتح صلاتي بانتظام لتحديث المواقيت المتغيرة.','GeoNames attribution':'مصدر بيانات GeoNames','Offline city data: GeoNames, CC BY 4.0. Calendar month boundaries: OpenJDK Hijrah-umalqura.':'بيانات المدن: GeoNames بترخيص CC BY 4.0. بدايات الأشهر: OpenJDK Hijrah-umalqura.'}
methods={'MUSLIM_WORLD_LEAGUE':'mwl','ISNA':'isna','EGYPTIAN':'egyptian','UMM_AL_QURA':'umm_al_qura','KARACHI':'karachi','TEHRAN':'tehran','SHIA_ITHNA_ASHARI':'shia_ithna_ashari','GULF':'gulf','KUWAIT':'kuwait','QATAR':'qatar','SINGAPORE':'singapore','TURKEY':'turkey','FRANCE_UOIF':'france_uoif','RUSSIA':'russia'}
observances={'HIJRI_NEW_YEAR':'new_year','TASUA':'tasua','ASHURA':'ashura','WHITE_DAY':'white_day','RAMADAN':'ramadan','RAMADAN_START':'ramadan_start','RAMADAN_LAST_TEN_NIGHTS':'last_ten_nights','RAMADAN_ODD_NIGHT':'odd_night','EID_AL_FITR':'eid_fitr','FIRST_TEN_DHU_AL_HIJJAH':'first_ten_dhul_hijjah','TARWIYAH':'tarwiyah','ARAFAH':'arafah','EID_AL_ADHA':'eid_adha','TASHREEQ':'tashreeq','FASTING_PROHIBITED':'fasting_prohibited'}
for lang,folder in [('en','values'),('ar','values-ar')]:
 catalog={e.attrib['name']:''.join(e.itertext()) for e in ET.parse(f'app/src/main/res/{folder}/strings.xml').getroot() if e.tag=='string'}
 strings={k:(v if lang=='ar' else k) for k,v in translations.items()}
 for k,v in methods.items():strings[k]=catalog['calc_method_'+v]
 for k,v in observances.items():strings[k]=catalog['hijri_observance_'+v]
 for k in ['ANGLE_BASED','MIDNIGHT','ONE_SEVENTH','NONE']:strings[k]=catalog['high_latitude_'+k.lower()]
 for k,en,ar in [('FAJR','Fajr','الفجر'),('SUNRISE','Sunrise','الشروق'),('DHUHR','Dhuhr','الظهر'),('ASR','Asr','العصر'),('MAGHRIB','Maghrib','المغرب'),('ISHA','Isha','العشاء')]:strings[k]=ar if lang=='ar' else en;strings[en]=strings[k]
 out=Path('iosApp/SharedPresentation')/(lang+'.lproj');out.mkdir(parents=True,exist_ok=True)
 (out/'Localizable.strings').write_text('\n'.join(json.dumps(k,ensure_ascii=False)+' = '+json.dumps(v.replace('\\"','"'),ensure_ascii=False)+';' for k,v in sorted(strings.items()))+'\n',encoding='utf-8')
 arplist={'NSLocationWhenInUseUsageDescription':'يستخدم صلاتي إحداثياتك لحساب المواقيت وتسمية موقعك باستخدام قاعدة المدن دون اتصال.','NSAlarmKitUsageDescription':'اسمح لصلاتي بجدولة منبهات النظام للصلوات التي تختارها.'}
 (out/'InfoPlist.strings').write_text('\n'.join(json.dumps(k)+' = '+json.dumps(v if lang=='ar' else {'NSLocationWhenInUseUsageDescription':'Salati uses your coordinates to calculate prayer times and label your location offline.','NSAlarmKitUsageDescription':'Allow Salati to schedule system alarms for prayers you choose.'}[k],ensure_ascii=False)+';' for k,v in arplist.items()),encoding='utf-8')
# Generate the shared recording catalogue from Android metadata rather than filename guesses.
models=Path('app/src/main/java/com/prayertimes/data/models/PrayerModels.kt').read_text(encoding='utf-8')
engine=Path('app/src/main/java/com/prayertimes/audio/AthanAudioEngine.kt').read_text(encoding='utf-8')
metadata={key:(en,ar) for key,en,ar in re.findall(r'\s+(ATHAN_\w+)\("([^"\n]*)", "[^"\n]*", "([^"\n]*)", true\)',models)}
mapping=re.findall(r'NotificationSoundType\.(ATHAN_\w+) -> R.raw.(\w+)',engine)
recordings=[]
for key,file in mapping:
 if key in metadata:
  en,ar=metadata[key]
  recordings.append({'id':file,'english':en,'arabic':ar})
Path('iosApp/Salati/Recordings.json').write_text(json.dumps(recordings,ensure_ascii=False,indent=2),encoding='utf-8')
